// MARK: - Color Extension

extension Color {
    init?(hex: String) {
        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var int: UInt64 = 0
        Scanner(string: hex).scanHexInt64(&int)
        let a, r, g, b: UInt64
        switch hex.count {
        case 3: // RGB (12-bit)
            (a, r, g, b) = (255, (int >> 8) * 17, (int >> 4 & 0xF) * 17, (int & 0xF) * 17)
        case 6: // RGB (24-bit)
            (a, r, g, b) = (255, int >> 16, int >> 8 & 0xFF, int & 0xFF)
        case 8: // ARGB (32-bit)
            (a, r, g, b) = (int >> 24, int >> 16 & 0xFF, int >> 8 & 0xFF, int & 0xFF)
        default:
            return nil
        }
        self.init(
            .sRGB,
            red: Double(r) / 255,
            green: Double(g) / 255,
            blue: Double(b) / 255,
            opacity: Double(a) / 255
        )
    }

    func toHex() -> String {
        guard let components = NSColor(self).cgColor.components, components.count >= 3 else {
            return "#000000"
        }
        let r = Float(components[0])
        let g = Float(components[1])
        let b = Float(components[2])
        return String(format: "#%02lX%02lX%02lX", lroundf(r * 255), lroundf(g * 255), lroundf(b * 255))
    }
}

#endif

// MARK: - Font Size Presets

enum FontSizePreset: CaseIterable, Identifiable {
    case small
    case medium
    case large
    case extraLarge

    var id: String { label }

    var label: String {
        switch self {
        case .small: return "Small"
        case .medium: return "Medium"
        case .large: return "Large"
        case .extraLarge: return "X-Large"
        }
    }

    var size: Double {
        switch self {
        case .small: return 12
        case .medium: return 16
        case .large: return 20
        case .extraLarge: return 24
        }
    }
}

// MARK: - Theme Presets

enum ThemePreset: CaseIterable, Identifiable {
    case light
    case sepia
    case dark
    case highContrast

    var id: String { label }

    var label: String {
        switch self {
        case .light: return "Light"
        case .sepia: return "Sepia"
        case .dark: return "Dark"
        case .highContrast: return "High Contrast"
        }
    }

    var backgroundColor: String {
        switch self {
        case .light: return "#FFFFFF"
        case .sepia: return "#F4ECD8"
        case .dark: return "#1C1C1E"
        case .highContrast: return "#000000"
        }
    }

    var textColor: String {
        switch self {
        case .light: return "#000000"
        case .sepia: return "#5B4636"
        case .dark: return "#EBEBF5"
        case .highContrast: return "#FFFFFF"
        }
    }

    func apply(to settings: AppSettings) {
        settings.backgroundColor = backgroundColor
        settings.textColor = textColor
    }

    func matches(_ settings: AppSettings) -> Bool {
        settings.backgroundColor == backgroundColor && settings.textColor == textColor
    }
}

