struct HighlightsView: View {
    let highlights: [Highlight]
    let bookTitle: String
    let bookAuthor: String
    let onSelectHighlight: (Highlight) -> Void
    let onDeleteHighlight: (UUID) -> Void

    @State private var showingExportSheet = false
    @State private var showingExportSuccess = false
    @State private var exportErrorMessage: String?

    var body: some View {
        Group {
            if highlights.isEmpty {
                ContentUnavailableView(
                    "No Highlights",
                    systemImage: "highlighter",
                    description: Text("Select text while reading to create highlights and annotations")
                )
            } else {
                List {
                    ForEach(highlights) { highlight in
                        HighlightRow(
                            highlight: highlight,
                            onTap: {
                                onSelectHighlight(highlight)
                            }
                        )
                        .swipeActions(edge: .trailing, allowsFullSwipe: true) {
                            Button(role: .destructive) {
                                onDeleteHighlight(highlight.id)
                            } label: {
                                Label("Delete", systemImage: "trash")
                            }
                        }
                    }
                }
                .listStyle(.inset)
            }
        }
        .toolbar {
            ToolbarItem {
                Button {
                    showingExportSheet = true
                } label: {
                    Label("Export Highlights", systemImage: "square.and.arrow.up")
                }
                .disabled(highlights.isEmpty)
            }
        }
        .alert("Export Successful", isPresented: $showingExportSuccess) {
            Button("OK", role: .cancel) { }
        } message: {
            Text("Your highlights have been exported successfully.")
        }
        .alert("Export Failed", isPresented: .constant(exportErrorMessage != nil)) {
            Button("OK", role: .cancel) {
                exportErrorMessage = nil
            }
        } message: {
            Text(exportErrorMessage ?? "An unknown error occurred.")
        }
    }
}

struct HighlightRow: View {
    let highlight: Highlight
    let onTap: () -> Void

    @State private var isHovering = false

    var body: some View {
        Button(action: onTap) {
            HStack(spacing: 0) {
                // Accent bar
                Rectangle()
                    .fill(
                        LinearGradient(
                            colors: [highlight.color.swiftUIColor, highlight.color.swiftUIColor.opacity(0.6)],
                            startPoint: .top,
                            endPoint: .bottom
                        )
                    )
                    .frame(width: 3)
                    .opacity(isHovering ? 1.0 : 0.6)

                VStack(alignment: .leading, spacing: 8) {
                    // Highlighted text
                    HStack(spacing: 8) {
                        ZStack {
                            Circle()
                                .fill(
                                    LinearGradient(
                                        colors: [highlight.color.swiftUIColor.opacity(0.3), highlight.color.swiftUIColor.opacity(0.2)],
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    )
                                )
                                .frame(width: 24, height: 24)

                            Image(systemName: "highlighter")
                                .font(.system(size: 11))
                                .foregroundStyle(highlight.color.swiftUIColor)
                        }

                        Text(highlight.selectedText)
                            .font(.system(size: 14, weight: .medium))
                            .foregroundStyle(.primary)
                            .lineLimit(3)
                            .fixedSize(horizontal: false, vertical: true)

                        Spacer()
                    }

                    // Annotation if present
                    if let annotation = highlight.annotation, !annotation.isEmpty {
                        HStack(spacing: 0) {
                            Rectangle()
                                .fill(highlight.color.swiftUIColor.opacity(0.4))
                                .frame(width: 2)

                            Text(annotation)
                                .font(.system(size: 13))
                                .foregroundStyle(.secondary)
                                .lineLimit(2)
                                .padding(.leading, 8)
                        }
                        .padding(.leading, 12)
                    }

                    // Thread info if present
                    if !highlight.threads.isEmpty {
                        HStack(spacing: 6) {
                            Image(systemName: "bubble.left.and.bubble.right")
                                .font(.system(size: 10))
                                .foregroundStyle(.tertiary)

                            let messageCount = highlight.threads.reduce(0) { $0 + $1.messages.count }
                            Text("\(highlight.threads.count) thread\(highlight.threads.count == 1 ? "" : "s"), \(messageCount) message\(messageCount == 1 ? "" : "s")")
                                .font(.system(size: 11))
                                .foregroundStyle(.tertiary)
                        }
                        .padding(.leading, 12)
                    }

                    // Creation date
                    HStack(spacing: 4) {
                        Image(systemName: "clock")
                            .font(.system(size: 10))
                            .foregroundStyle(.tertiary)

                        Text(highlight.createdAt.formatted(date: .abbreviated, time: .shortened))
                            .font(.system(size: 11))
                            .foregroundStyle(.tertiary)
                    }
                    .padding(.leading, 12)
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 10)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .background(
            isHovering
                ? Color.secondary.opacity(0.05)
                : Color.clear
        )
        .clipShape(RoundedRectangle(cornerRadius: 8))
        .onHover { hovering in
            withAnimation(.easeInOut(duration: 0.2)) {
                isHovering = hovering
            }
        }
    }
}

