                            .foregroundStyle(.secondary)
                            .accessibilityIdentifier("chapterPosition")
                        Text("•")
                            .font(.caption2)
                            .foregroundStyle(.tertiary)
                        Text("\(chapterPercentage)% in chapter")
                            .font(.caption2)
                            .foregroundStyle(.secondary)
