                    data: data,
                    suggestedFilename: suggestedFilename,
                    contentType: selectedFormat.fileExtension == "csv" ? .commaSeparatedText : .plainText
                ) != nil {
                    dismiss()
                    onExportSuccess()
                } else {
                    // User cancelled or save failed
                    isExporting = false
