/* Crux Reader Styles */

:root {
    --crux-bg: #FFFFFF;
    --crux-text: #2C2825;
    --crux-text-muted: #6B6561;
    --crux-accent: #8B4513;
    --crux-selection: rgba(139, 69, 19, 0.18);
    --crux-rule: rgba(44, 40, 37, 0.12);
    --crux-highlight: rgba(139, 69, 19, 0.15);
    --crux-highlight-hover: rgba(139, 69, 19, 0.25);
    --crux-font-body: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
    --crux-font-display: "New York", "Iowan Old Style", Georgia, serif;
    --crux-font-ui: -apple-system, BlinkMacSystemFont, sans-serif;
}

@media (prefers-color-scheme: dark) {
    :root {
        --crux-bg: #1C1A18;
        --crux-text: #E8E4DF;
        --crux-text-muted: #9A958F;
        --crux-accent: #D4A574;
        --crux-selection: rgba(212, 165, 116, 0.25);
        --crux-rule: rgba(232, 228, 223, 0.1);
        --crux-highlight: rgba(212, 165, 116, 0.2);
        --crux-highlight-hover: rgba(212, 165, 116, 0.35);
    }
}

/* Base */
html, body {
    margin: 0;
    padding: 0;
    background: var(--crux-bg);
    -webkit-font-smoothing: antialiased;
}

/* Layout */
.crux-reader-wrapper {
    display: flex;
    max-width: 1400px;
    margin: 0 auto;
    justify-content: center;
}

.crux-content {
    flex: 0 1 680px;
    padding: 48px 56px;
    font-family: var(--crux-font-body);
    font-size: 18px;
    line-height: 1.75;
    letter-spacing: 0.01em;
    color: var(--crux-text);
    text-rendering: optimizeLegibility;
    font-feature-settings: "kern" 1, "liga" 1;
}

.crux-margin {
    flex: 0 0 280px;
    position: relative;
    padding: 48px 12px;
}

.crux-margin-left {
    padding-left: 12px;
    padding-right: 0;
}

.crux-margin-right {
    padding-left: 0;
    padding-right: 12px;
}

/* iOS platform overrides */
:root[data-platform="ios"] .crux-content {
    padding: 24px 20px;
}

:root[data-platform="ios"] .crux-reader-wrapper {
    max-width: 1100px;
}

/* Paragraphs */
.crux-content p {
    margin: 0 0 1.5em 0;
    text-align: justify;
    hyphens: auto;
    -webkit-hyphens: auto;
}

.crux-content p + p {
    text-indent: 1.5em;
    margin-top: -0.5em;
}

/* Headings */
.crux-content h1, .crux-content h2, .crux-content h3, .crux-content h4 {
    font-family: var(--crux-font-display);
    font-weight: 500;
    letter-spacing: -0.01em;

