.crux-content h1, .crux-content h2, .crux-content h3, .crux-content h4 {
    font-family: var(--crux-font-display);
    font-weight: 500;
    letter-spacing: -0.01em;
    line-height: 1.25;
    margin: 2em 0 0.75em 0;
    color: var(--crux-text);
    text-indent: 0;
}

.crux-content h1 {
    font-size: 2em;
    font-weight: 400;
    letter-spacing: -0.02em;
    margin-top: 0;
    margin-bottom: 1.5em;
    text-align: center;
}

.crux-content h2 {
    font-size: 1.4em;
    margin-top: 2.5em;
    padding-top: 1.5em;
    border-top: 1px solid var(--crux-rule);
}

.crux-content h3 {
    font-size: 1.15em;
    font-style: italic;
    font-weight: 400;
}

/* Blockquotes */
.crux-content blockquote {
    margin: 2em 0;
